let token=sessionStorage.getItem(tokenKey)||'', user=(()=>{try{return JSON.parse(sessionStorage.getItem(userKey)||'null')}catch{return null}})(), persistent=null, view='dashboard', cache={}, employeeQuery='', recordQuery='', recordTypeFilter='Todos', recordsEmployeeId='', recordsMonth= new Date().getMonth()+1, recordsYear=new Date().getFullYear(), recordsSearch='', recordsBranch='', recordsSelectedDate='', recordsReport=null, requestQuery='', requestStatusFilter='Todos';
