const AUTH_DB='certus-auth-persistence-v1',AUTH_STORE='keys';function authDb(){return new Promise((ok,no)=>{const r=indexedDB.open(AUTH_DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(AUTH_STORE);r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}async function authKey(db){let k=await new Promise((ok,no)=>{const r=db.transaction(AUTH_STORE).objectStore(AUTH_STORE).get('refresh-key');r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});if(!k){k=await crypto.subtle.generateKey({name:'AES-GCM',length:256},false,['encrypt','decrypt']);await new Promise((ok,no)=>{const tx=db.transaction(AUTH_STORE,'readwrite');tx.objectStore(AUTH_STORE).put(k,'refresh-key');tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}return k}async function savePersistentSession(session){const db=await authDb();try{const k=await authKey(db),iv=crypto.getRandomValues(new Uint8Array(12)),plain=new TextEncoder().encode(session.refresh_token),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},k,plain),meta={session_id:session.session_id,company_slug:session.company_slug,iv:[...iv],cipher:[...new Uint8Array(cipher)]};localStorage.setItem(persistentKey,JSON.stringify(meta));persistent={...meta,refresh_token:session.refresh_token}}finally{db.close()}}async function loadPersistentSession(){try{const meta=JSON.parse(localStorage.getItem(persistentKey)||'null');if(!meta?.session_id||!meta?.company_slug||!meta?.iv||!meta?.cipher)return null;const db=await authDb();try{const k=await authKey(db),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(meta.iv)},k,new Uint8Array(meta.cipher));return{...meta,refresh_token:new TextDecoder().decode(plain)}}finally{db.close()}}catch{return null}}function clearPersistentSession(){persistent=null;localStorage.removeItem(persistentKey);indexedDB.deleteDatabase(AUTH_DB)}
let refreshing=null;async function refreshSession(){if(!persistent?.session_id||!persistent?.refresh_token||!persistent?.company_slug)return false;if(!refreshing)refreshing=(async()=>{try{const r=await fetch(API+'/api/auth/refresh',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({session_id:persistent.session_id,company_slug:persistent.company_slug,refresh_token:persistent.refresh_token})}),d=await r.json().catch(()=>({}));if(!r.ok||!d.access_token){if(r.status===401||r.status===400){clearPersistentSession();return false}throw Error(d.error||'Não foi possível atualizar a sessão.')}token=d.access_token;user={...(user||{}),...d.user};sessionStorage.setItem(tokenKey,token);sessionStorage.setItem(userKey,JSON.stringify(user));return true}catch(e){throw e}finally{refreshing=null}})();return refreshing}async function api(path,opts={}){const make=()=>{const headers={'Accept':'application/json',...(opts.body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:`Bearer ${token}`}:{}) ,...(opts.headers||{})};return fetch(API+path,{...opts,headers})};let r=await make();if(r.status===401&&persistent&&path!=='/api/auth/refresh'){try{if(await refreshSession())r=await make()}catch{throw Error('Não foi possível validar sua sessão agora. Confira a conexão e tente novamente.')}}let data={};try{data=await r.json()}catch{}if(r.status===401){logout('Sessão encerrada por segurança. Entre novamente.');throw Error('Sessão expirada')}if(!r.ok)throw Error(data.error||`Falha na API (${r.status})`);return data}
