function initialPasswordGate(){root.innerHTML=`<main class="login"><form class="card login-card" id="initial-password-form"><img class="brand-logo" src="./certus-logo-color.png" alt="Certus by VagasIO"><p class="eyebrow">Primeiro acesso</p><h1>Crie sua senha pessoal</h1><p>Por segurança, altere a senha temporária antes de continuar.</p><div id="initial-password-message" class="message" role="alert" hidden></div><label>Nova senha<input name="new_password" type="password" autocomplete="new-password" minlength=14 required></label><label>Confirme a nova senha<input name="confirm_password" type="password" autocomplete="new-password" minlength=14 required></label><button class="primary">Salvar nova senha</button></form></main>`;$('#initial-password-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),a=String(f.get('new_password')),b=String(f.get('confirm_password')),m=$('#initial-password-message'),btn=e.currentTarget.querySelector('button');if(a!==b){m.hidden=false;m.className='message bad';m.textContent='As senhas não coincidem.';return}if(a.length<14){m.hidden=false;m.className='message bad';m.textContent='Use pelo menos 14 caracteres.';return}btn.disabled=true;btn.textContent='Salvando…';try{await api('/api/account/initial-password',{method:'POST',body:JSON.stringify({new_password:a})});token='';user=null;sessionStorage.removeItem(tokenKey);sessionStorage.removeItem(userKey);clearPersistentSession();login('Senha alterada. Entre novamente com a nova senha.')}catch(err){m.hidden=false;m.className='message bad';m.textContent=err.message;btn.disabled=false;btn.textContent='Salvar nova senha'}}}
