function shell(){if(user.role==='employee'&&view==='dashboard')view='worker';if(user.role!=='employee'&&view==='worker')view='dashboard';root.innerHTML=`<div class="layout"><aside class="side" id="company-sidebar"><div class="side-heading"><div class="brand"><img class="brand-logo" src="./certus-logo-color.png" alt="Certus by VagasIO"></div><button id="close-menu" class="close-menu" aria-label="Fechar menu">×</button></div><div class="org"><small>EMPRESA</small><b id="org"></b></div><nav aria-label="Menu principal">${(user.role==='employee'?Object.entries(views):['dashboard','employees','records','requests','users','bank','schedules','terminals','reports','password','settings','branches','anomalies'].map(k=>[k,views[k]])).filter(([k])=>user.role==='employee'?k==='worker':k!=='worker'&&k!=='timesheet'&&k!=='unavailable'&&(k!=='anomalies'||['company_admin','manager','hr','supervisor'].includes(user.role))&&(k!=='bank'||['company_admin','manager','hr'].includes(user.role))&&(k!=='users'||['company_admin','hr'].includes(user.role))&&(k!=='terminals'||['company_admin','hr'].includes(user.role))).map(([k,v])=>`<button data-view="${k}">${v}</button>`).join('')}</nav>${user.role==='employee'?'<nav class="account-menu" aria-label="Conta"><button data-view="timesheet">Espelho de ponto</button><button data-view="password">Segurança</button></nav>':''}<div class="side-bottom"><p class="side-help"><strong>Ajuda e privacidade</strong><span>Seus dados ficam protegidos.</span></p><button id="logout" class="logout">Sair da conta</button></div></aside><button class="nav-scrim" id="nav-scrim" aria-label="Fechar menu" hidden></button><main class="main"><header><button id="menu-toggle" class="menu-toggle" aria-label="Abrir menu" aria-controls="company-sidebar" aria-expanded="false"><span></span><span></span><span></span></button><div class="page-heading"><small id="crumb"></small><h1 id="title"></h1></div><div id="identity"></div>${user.role==='employee'?'<span class="worker-header-avatar" aria-hidden="true"></span>':''}</header><div id="message" class="message" role="status" aria-live="polite" hidden></div><section id="content" tabindex="-1"></section><footer><div class="footer-brand"><img src="./certus-logo-color.png" alt="Certus by VagasIO"></div><span>Certus by VagasIO</span></footer></main></div>`;$('#org').textContent=user.company.name;const roleNames={company_admin:'Administrador titular',manager:'Gerente',hr:'RH',supervisor:'Supervisor',employee:'Funcionário'};$('#identity').textContent=user.role==='employee'?(user.employee_name||user.name||'Colaborador'):`${user.name} · ${roleNames[user.role]||'Usuário'}`;const workerAvatar=$('.worker-header-avatar');if(workerAvatar){const workerName=user.employee_name||user.name||'';workerAvatar.textContent=workerName.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()} $('#logout').onclick=()=>logout('Você saiu da conta.');const sidebar=$('#company-sidebar'),scrim=$('#nav-scrim'),toggle=$('#menu-toggle');const closeMenu=()=>{sidebar.classList.remove('open');scrim.hidden=true;toggle.setAttribute('aria-expanded','false');document.body.classList.remove('menu-open')};toggle.onclick=()=>{const opened=sidebar.classList.toggle('open');scrim.hidden=!opened;toggle.setAttribute('aria-expanded',String(opened));document.body.classList.toggle('menu-open',opened)};$('#close-menu').onclick=closeMenu;scrim.onclick=closeMenu;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});$$('[data-view]').forEach(b=>b.onclick=()=>{closeMenu();load(b.dataset.view)});load(view)}
