async function load(v){view=v;$$('[data-view]').forEach(b=>{const active=b.dataset.view===v;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#title').textContent=views[v];$('#title').tabIndex=-1;$('#crumb').textContent=user.company.name;message('');$('#content').innerHTML='<div class="card">Carregando…</div>';try{$('#content').innerHTML=await render(v);bind()}catch(e){if(v==='records'&&e.message==='Active employee profile not found'&&(recordsEmployeeId||new URLSearchParams(location.search).has('employee_id'))){recordsEmployeeId='';recordsSelectedDate='';history.replaceState(null,'',location.pathname);await load('records');message('O colaborador deste link não foi localizado nesta empresa. Selecione um colaborador da lista atualizada.',true);return}$('#content').innerHTML=`<article class="card error" role="alert"><h2>Não foi possível abrir esta área</h2><p>${esc(e.message)}</p><button class="secondary" type="button" id="retry-view">Tentar novamente</button></article>`;$('#retry-view')?.addEventListener('click',()=>load(v))}}
const formatDateTime=v=>{if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(d)};
const eventLabel=v=>({entry:'Entrada',break_start:'Saída para intervalo',break_end:'Retorno do intervalo',exit:'Saída'})[v]||String(v||'—');const requestLabel=x=>({day_abono:'Abono dia',hours_abono:'Abono horas',clock_adjustment:eventLabel(x.requested_type),clock_retification:'Retificar marcação'})[x.request_kind]||eventLabel(x.requested_type);const requestDateLabel=x=>x.request_kind==='day_abono'?`${String(x.abono_date||'').slice(0,10)}${x.abono_end_date&&String(x.abono_end_date).slice(0,10)!==String(x.abono_date).slice(0,10)?` a ${String(x.abono_end_date).slice(0,10)}`:''}`:formatDateTime(x.requested_at);const statusLabel=v=>({active:'Ativo',inactive:'Inativo',leave:'Afastado',pending:'Pendente',approved:'Aprovado',rejected:'Recusado',needs_info:'Revisar',validated:'Validado',review:'Em revisão',personal_device:'Portal do colaborador',shared_terminal:'Terminal compartilhado',admin_demo:'Correção administrativa'})[v]||String(v||'—');const stat=(k,v)=>`<article class="card stat"><small>${esc(k)}</small><strong>${esc(v)}</strong></article>`;
let workerRecordsExpanded=false;let faceApiReady=null;async function loadFaceApi(){if(faceApiReady)return faceApiReady;faceApiReady=new Promise((resolve,reject)=>{if(window.faceapi)return resolve(window.faceapi);const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.15/dist/face-api.js';script.onload=()=>resolve(window.faceapi);script.onerror=()=>reject(Error('Não foi possível carregar o reconhecimento facial')) ;document.head.append(script)}).then(async f=>{const base='https://cdn.jsdelivr.net/gh/vladmandic/face-api/model';await Promise.all([f.nets.ssdMobilenetv1.loadFromUri(base),f.nets.faceLandmark68Net.loadFromUri(base),f.nets.faceRecognitionNet.loadFromUri(base)]);return f});faceApiReady.catch(()=>{faceApiReady=null});return faceApiReady}
async function faceDescriptor(video){const f=await loadFaceApi();const r=await f.detectSingleFace(video,new f.SsdMobilenetv1Options({minConfidence:0.65})).withFaceLandmarks().withFaceDescriptor();if(!r)throw Error('__FACE_NOT_FOUND__');return Array.from(r.descriptor)}
async function withCamera(run){if(!navigator.mediaDevices?.getUserMedia)throw Error('Este aparelho/navegador não liberou acesso à câmera');const video=document.createElement('video');video.autoplay=true;video.muted=true;video.playsInline=true;const dialog=document.createElement('dialog');dialog.className='dialog face-dialog';dialog.innerHTML='<form class="card dialog-card face-dialog-card" method="dialog"><button class="face-close" value="cancel" aria-label="Cancelar reconhecimento">×</button><span class="face-eyebrow">CERTUS · MEU PONTO</span><h2>Reconhecimento facial</h2><p class="face-description">Centralize o rosto no círculo. A câmera analisa a imagem e confirma com o cadastro automaticamente. Foto e vídeo não são enviados nem armazenados.</p><div class="face-camera-ring"><div id="face-camera"></div><span class="face-guide" aria-hidden="true"></span></div><div class="face-progress" role="status" aria-live="polite"><span class="face-pulse"></span><span id="face-progress-text">Iniciando câmera…</span></div><button class="secondary face-cancel" value="cancel">Cancelar</button></form>';dialog.querySelector('#face-camera').append(video);document.body.append(dialog);const progress=dialog.querySelector('#face-progress-text');let stream,closed=false;try{dialog.showModal();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:640},aspectRatio:{ideal:1}},audio:false});video.srcObject=stream;await new Promise((resolve,reject)=>{video.onloadedmetadata=resolve;video.onerror=()=>reject(Error('Câmera indisponível'))});await video.play().catch(()=>{});return await new Promise((resolve,reject)=>{dialog.addEventListener('cancel',()=>{closed=true;reject(Error('Reconhecimento cancelado'))},{once:true});dialog.addEventListener('close',()=>{if(!closed)reject(Error('Reconhecimento cancelado'))},{once:true});const loop=async()=>{if(closed||!dialog.open)return;try{const result=await run(video,text=>{if(progress)progress.textContent=text});closed=true;resolve(result)}catch(e){if(closed||!dialog.open)return;if(e?.message==='__FACE_NOT_FOUND__'||e?.message==='__FACE_LOW_QUALITY__'){if(progress)progress.textContent=e.message==='__FACE_LOW_QUALITY__'?'Ajuste a distância e a iluminação; mantenha o rosto dentro do círculo…':'Posicione o rosto dentro do círculo…';setTimeout(loop,500);return}if(e?.message==='__FACE_MISMATCH__'){if(progress)progress.textContent='Rosto não confirmado. Ajuste a posição e tente novamente…';setTimeout(loop,650);return}closed=true;reject(e)}};loop()})}finally{stream?.getTracks().forEach(t=>t.stop());if(dialog.open)dialog.close();dialog.remove()}}
async function faceStatus(){return api('/api/employee/face-profile')}
async function captureFaceProfile(video,state){const f=await loadFaceApi(),samples=[];let previous=null;while(samples.length<5){const r=await f.detectSingleFace(video,new f.SsdMobilenetv1Options({minConfidence:0.65})).withFaceLandmarks().withFaceDescriptor();if(!r)throw Error('__FACE_NOT_FOUND__');const box=r.detection.box,frameWidth=video.videoWidth||640;if(r.detection.score<0.75||box.width/frameWidth<0.18)throw Error('__FACE_LOW_QUALITY__');const d=Array.from(r.descriptor);if(previous){const delta=Math.sqrt(previous.reduce((sum,v,i)=>sum+(v-d[i])**2,0));if(delta>=0.32){samples.length=0;previous=d;state('Mantenha o rosto parado e bem iluminado; estabilizando a captura…');throw Error('__FACE_NOT_FOUND__')}}previous=d;samples.push(d);state(`Captura nítida ${samples.length} de 5…`);if(samples.length<5)await new Promise(resolve=>setTimeout(resolve,180))}return samples[0].map((_,i)=>samples.reduce((sum,d)=>sum+d[i],0)/samples.length)}
async function enrollFace(){try{if(!confirm('Consentimento separado: autoriza armazenar seu modelo facial para conferir suas marcações? O reconhecimento não prova presença real.'))return;const descriptor=await withCamera(async(video,state)=>captureFaceProfile(video,state));await api('/api/employee/face-profile',{method:'POST',body:JSON.stringify({consent:true,descriptor})});message('Cadastro facial realizado com cinco capturas nítidas e consistentes. Para refazer, solicite liberação do gestor no terminal compartilhado.')}catch(e){message(e.message,true)}await load('worker')}
function timesheetMinutes(value){if(!Number.isFinite(value))return 'Não informado';const sign=value<0?'−':'';const n=Math.abs(Math.round(value));return `${sign}${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function timesheetCount(report){return (report?.days||[]).reduce((n,d)=>n+(d.marks?.length||0),0)}
function reportDuration(value){return Number.isInteger(value)?`${String(Math.floor(Math.abs(value)/60)).padStart(2,'0')}h${String(Math.abs(value)%60).padStart(2,'0')}min`:'—'}
function reportSigned(value){return Number.isInteger(value)?`${value>0?'+':value<0?'-':''}${reportDuration(Math.abs(value))}`:'—'}
function reportSchedule(d){if(d.schedule?.restDay)return 'DSR';if(d.schedule?.pairs?.length)return d.schedule.pairs.map(p=>`${p.start||p.entry}–${p.end||p.exit}`).join(' / ');if(d.schedule?.start&&d.schedule?.end)return `${d.schedule.start}–${d.schedule.end}`;if(Number.isInteger(d.plannedMinutes))return `${reportDuration(d.plannedMinutes)} prevista`;return d.scheduleSource==='missing'?'Jornada não informada':'Programação não informada'}
